'use strict';
(()=>{
 const panel=document.createElement('article');panel.className='panel';panel.id='historyImportPanel';panel.innerHTML=`<div class="panel-head"><div><h2>导入历史记录</h2><p>补齐过去的收入与家庭总资产，只用于统计和曲线，不改银行卡余额，不自动推算历史支出，也不替代月度账户核对。</p></div><span class="status-tag">人民币汇总</span></div>
 <p id="historyPermission" class="muted"></p><form id="historyImportForm"><label class="field">导入内容<select id="historyKind"><option value="income">历史收入汇总（不限人数与期间）</option><option value="assets">历史家庭总资产</option></select></label>
 <label class="field" id="historyIncomeFormatField">表格格式<select id="historyIncomeFormat"><option value="general">通用表 · 每行一位成员的一段期间</option><option value="pair">快捷表 · 两个人的每月收入</option></select></label>
 <div id="historyMemberMap" class="form-grid"><label class="field">“成员一收入”这一列对应<select id="historyMember1"></select></label><label class="field">“成员二收入”这一列对应<select id="historyMember2"></select></label></div>
 <div class="history-template-actions"><button class="outline" type="button" id="historyTemplate">下载CSV模板</button><label class="outline history-file">上传CSV文件<input id="historyFile" type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values"></label></div>
 <p id="historyFormat" class="muted"></p><p id="historyMemberNames" class="muted"></p><label class="field">粘贴表格内容（包含表头）<textarea id="historyText" rows="8" spellcheck="false" required></textarea></label>
 <p class="muted">支持CSV或Excel复制粘贴，暂不直接读取xlsx。金额按人民币填写。通用表每行是一位成员在该期间的收入合计；成员须先在设置中添加。不同成员可填相同期间，同一成员的期间不能重叠。只有年合计时不会自动拆成月收入。每批最多2000行。</p>
 <label class="income-confirm"><input id="historyReplace" type="checkbox"><span>同一期间/成员或同一日期已有历史汇总时，更新为本次金额及备注（不会叠加）。</span></label>
 <div class="actions"><button class="solid" id="historyCheck" type="submit">检查并预览</button><button class="outline" id="historyCommit" type="button" disabled>确认导入</button></div></form><p id="historyStatus" role="status"></p><div id="historyPreview" hidden></div>
 <details id="historySaved"><summary>查看已导入的历史记录</summary><div class="history-saved-controls"><button class="outline" id="historyShowAll" type="button">在统计图中查看全部历史</button></div><div class="table-scroll"><table><thead><tr><th>类型</th><th>期间 / 日期</th><th>归属</th><th>人民币金额</th><th>备注</th></tr></thead><tbody id="historySavedRows"></tbody></table></div></details>`;
 document.querySelector('[data-page="settings"]').prepend(panel);
 for(const [page,kind,title,description]of [['income','income','有过去多年的收入记录？','按成员导入具体日期、月度、年度或自选期间的收入合计；保留两人月收入快捷表。'],['assets','assets','有以前的家庭总余额？','只知道某天的家庭总额也能补录，不必拆分到银行卡。']]){const a=document.createElement('article');a.className='panel history-entry';const div=document.createElement('div'),strong=document.createElement('strong'),p=document.createElement('p'),b=document.createElement('button');strong.textContent=title;p.textContent=description;p.className='muted';b.type='button';b.className='outline';b.textContent=kind==='income'?'导入历史收入':'导入历史总资产';div.append(strong,p);a.append(div,b);document.querySelector('[data-page="'+page+'"]').prepend(a);b.onclick=()=>{location.hash='#settings';$('historyKind').value=kind;changeKind();requestAnimationFrame(()=>$('historyKind').focus());};}
 const reportNotes=[];for(const page of ['overview','income']){const p=document.createElement('p');p.className='demo-notice';p.hidden=true;document.querySelector('[data-page="'+page+'"]').prepend(p);reportNotes.push(p);}
 window.FamilyHistory={renderStatus:r=>{for(const [i,p]of reportNotes.entries()){const r=FamilyPanelFilters.report(i===0?'overview-metrics':'income-details');p.hidden=!r.historical&&!r.partialHistory;p.textContent=(r.historical?'本区间含历史汇总。历史收入汇总不进入银行卡余额；家庭总额没有账户明细，收支外资产变动暂不计算。 ':'')+(r.partialHistory?'所选日期只覆盖部分汇总期间，该条收入未计入；请选择完整期间。':'');}}};
 let token=null,busy=false,fileSequence=0;
 function lockForm(value){for(const el of document.querySelectorAll("#historyImportForm input,#historyImportForm select,#historyImportForm textarea,#historyImportForm button"))if(el.id!=="historyCommit")el.disabled=value||(el.id==="historyCheck"&&window.currentFamilyUser?.role!=="admin");} function invalidate(){$('historyStatus').textContent='';token=null;$('historyCommit').disabled=true;$('historyPreview').hidden=true;}
 function changeKind(){invalidate();const income=$('historyKind').value==='income',pair=$('historyIncomeFormat').value==='pair';$('historyIncomeFormatField').hidden=!income;$('historyMemberMap').hidden=!income||!pair;$('historyFormat').textContent=!income?'表头：日期,家庭总资产,备注。只记家庭合计，不生成虚构账户。':pair?'表头：月份,成员一收入,成员二收入,备注。两列分别选择对应成员。空白表示未知，0表示确认没有收入。':'表头：期间,成员,收入金额,备注。期间可以写2018-01、2018、2018-01-15，或2018-01-01~2018-03-31。成员填写设置里的称呼（重名时使用下方编号）。空白不代表0，请省略未知记录。';$('historyText').placeholder=!income?'日期,家庭总资产,备注\n2018-12-31,300000,年末记录':pair?'月份,成员一收入,成员二收入,备注\n2018-01,10000,8000,历史记录':'期间,成员,收入金额,备注\n2018-01,成员称呼,10000,月收入\n2019,另一位成员称呼,120000,全年收入';}
 $('historyIncomeFormat').onchange=changeKind;
 function detectFormat(){if($('historyKind').value!=='income')return;const first=$('historyText').value.replace(/^\uFEFF/,'').split(/[\t,\r\n]/)[0],format=first==='月份'?'pair':first==='期间'?'general':null;if(format&&$('historyIncomeFormat').value!==format){$('historyIncomeFormat').value=format;changeKind();}}
 $('historyText').addEventListener('input',detectFormat);
 function refresh(){const profiles=D.memberProfiles||[];$('historyMemberNames').textContent='可用成员：'+profiles.map(p=>p.name+(profiles.filter(x=>x.name===p.name).length>1?'（编号：'+p.key+'）':' ')).join('、');for(const [id,index]of [['historyMember1',0],['historyMember2',1]]){const select=$(id),old=select.value;select.replaceChildren(new Option('请选择成员',''),...profiles.map(p=>new Option(p.name+(p.active?'':'（已移除）'),p.key)));select.value=profiles.some(p=>p.key===old)?old:profiles[index]?.key||'';}const admin=window.currentFamilyUser?.role==='admin';$('historyPermission').textContent=admin?'由管理员导入；预览不会写入，确认后才保存。':'家庭成员可以查看历史记录，导入及更正请管理员操作。';$('historyCheck').disabled=!admin;const rows=$('historySavedRows');rows.replaceChildren();for(const r of (D.history||[]).slice().sort((a,b)=>b.date.localeCompare(a.date))){const tr=document.createElement('tr');tr.dataset.historyKey=r.key;for(const value of [r.kind==='income'?'历史收入汇总':'历史家庭总额',FamilyHistoryPeriod.label(r),r.kind==='income'?memberName(r.member):'全家',money(r.cents),r.memo]){const td=document.createElement('td');td.textContent=value;tr.append(td);}rows.append(tr);}if(!rows.children.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='empty';td.textContent='尚未导入历史记录。';tr.append(td);rows.append(tr);}}
 for(const id of ['historyText','historyMember1','historyMember2','historyReplace'])$(id).addEventListener('input',invalidate);$('historyKind').onchange=changeKind;
 $('historyTemplate').onclick=()=>{const header=$('historyKind').value==='income'?($('historyIncomeFormat').value==='pair'?'月份,成员一收入,成员二收入,备注\r\n':'期间,成员,收入金额,备注\r\n'):'日期,家庭总资产,备注\r\n';download($('historyKind').value==='income'?'历史收入模板.csv':'历史家庭总资产模板.csv','\uFEFF'+header,'text/csv;charset=utf-8');};
 $('historyFile').onchange=async()=>{const seq=++fileSequence;invalidate();const f=$('historyFile').files[0];if(!f)return;try{if(f.size>900000)throw Error('请选择900KB以内的CSV文件。');const bytes=await f.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('gb18030',{fatal:true}).decode(bytes);if(seq!==fileSequence)return;$('historyText').value=text;detectFormat();$('historyStatus').textContent='文件已读取，请核对成员对应关系并检查预览。';}catch(e){if(seq===fileSequence)$('historyStatus').textContent=e.message;}};
 $('historyImportForm').onsubmit=async e=>{e.preventDefault();if(busy)return;detectFormat();invalidate();busy=true;fileSequence++;lockForm(true);$('historyCheck').disabled=true;try{const r=await api('/api/history/preview',{kind:$('historyKind').value,text:$('historyText').value,members:[$('historyMember1').value,$('historyMember2').value],replace:$('historyReplace').checked});token=r.token;const s=r.summary;$('historyStatus').textContent=`预览：新增 ${s.add} 条，更新 ${s.update} 条，跳过重复 ${s.skip} 条，冲突 ${s.conflict} 条。${s.conflict?'如要更正已有历史汇总，请勾选更新后重新检查。':s.add+s.update?'核对后点击确认导入。':'全部已导入，无需再次确认。'}`;$('historyCommit').disabled=!!s.conflict||s.add+s.update===0;const box=$('historyPreview');box.replaceChildren();const table=document.createElement('table'),thead=document.createElement('thead'),head=document.createElement('tr');for(const label of ['行','期间 / 日期','归属','金额','处理']){const th=document.createElement('th');th.textContent=label;head.append(th);}thead.append(head);table.append(thead);const body=document.createElement('tbody');for(const row of r.rows.slice(0,30)){const tr=document.createElement('tr');for(const v of [row.line,FamilyHistoryPeriod.label(row),row.kind==='income'?memberName(row.member):'全家',money(row.cents),row.action]){const td=document.createElement('td');td.textContent=v;tr.append(td);}body.append(tr);}table.append(body);const scroll=document.createElement('div');scroll.className='table-scroll';scroll.append(table);const note=document.createElement('p');note.className='muted';note.textContent=`共 ${r.rows.length} 条记录，下面最多展示前30条；只有确认后才会保存。`;box.append(note,scroll);box.hidden=false;}catch(x){$('historyStatus').textContent=x.message;}finally{busy=false;lockForm(false);$('historyCheck').disabled=window.currentFamilyUser?.role!=='admin';}};
 $('historyCommit').onclick=async()=>{if(!token||busy)return;busy=true;fileSequence++;lockForm(true);$('historyCommit').disabled=true;try{const r=await api('/api/history/commit',{token});invalidate();await refreshLedger();$('historySaved').open=true;$('historyStatus').textContent=`导入完成：新增 ${r.add} 条，更新 ${r.update} 条，跳过 ${r.skip} 条。图表已更新；银行卡余额没有改变。`;}catch(e){$('historyStatus').textContent=e.message;invalidate();}finally{busy=false;lockForm(false);}};
 $('historyShowAll').onclick=()=>{FamilyPanelFilters.showHistory();location.hash='#income';};
 document.addEventListener('family-ledger-ready',()=>{invalidate();refresh();});document.addEventListener('family-session-ready',refresh);document.addEventListener('family-app-ready',refresh);changeKind();refresh();
})();
